// Cloudflare Worker entry: serves the Next.js app (built by OpenNext) and runs the publisher on a schedule.
// @ts-ignore — .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

/** CRON_SECRET from Worker secrets, or the one the app generated and stored in D1 (see src/lib/secrets.ts). */
async function cronSecret(env: CloudflareEnv): Promise<string> {
  const fromEnv = (env as unknown as Record<string, unknown>).CRON_SECRET;
  if (typeof fromEnv === "string" && fromEnv) return fromEnv;
  const read = () => env.DB.prepare("SELECT value FROM app_secrets WHERE name = 'CRON_SECRET'").first<{ value: string }>();
  const row = await read();
  if (row?.value) return row.value;
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  const value = [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
  await env.DB.prepare("INSERT OR IGNORE INTO app_secrets (name, value) VALUES ('CRON_SECRET', ?)").bind(value).run();
  return (await read())!.value;
}

export default {
  fetch: handler.fetch,

  // Cron Trigger (every minute, see wrangler.jsonc): hand off to the protected publish route.
  async scheduled(_controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    const url = new URL("/api/cron/publish", env.APP_URL || "https://postpilot.internal");
    const res = await handler.fetch(
      new Request(url, { headers: { authorization: `Bearer ${await cronSecret(env)}` } }),
      env,
      ctx,
    );
    if (!res.ok) console.error("[cron] publish run failed", res.status, await res.text());
  },
} satisfies ExportedHandler<CloudflareEnv>;
